import java.lang.StringBuffer;

public class Example {
    public void method() {
        StringBuffer localBuffer = new StringBuffer();
        localBuffer.append("test");
        String s = localBuffer.toString();

        StringBuffer anotherLocal = new StringBuffer(10);
        anotherLocal.append("hello");
    }

    private StringBuffer fieldBuffer = new StringBuffer(); // Should not match
    public static StringBuffer staticFieldBuffer = new StringBuffer("static"); // Should not match

    public StringBuffer createBuffer() {
        return new StringBuffer("created"); // Should not match
    }
}

afterExample:
import java.lang.StringBuffer;
import java.lang.StringBuilder;

public class Example {
    public void method() {
        StringBuilder localBuffer = new StringBuilder();
        localBuffer.append("test");
        String s = localBuffer.toString();

        StringBuilder anotherLocal = new StringBuilder(10);
        anotherLocal.append("hello");
    }

    private StringBuffer fieldBuffer = new StringBuffer(); // Still StringBuffer
    public static StringBuffer staticFieldBuffer = new StringBuffer("static"); // Still StringBuffer

    public StringBuffer createBuffer() {
        return new StringBuffer("created"); // Still StringBuffer
    }
}

