import java.lang.StringBuffer;

public class NegativeExample {
    // Field initialization - should not be converted due to potential thread-safety issues
    private StringBuffer instanceBuffer = new StringBuffer();

    // Static field initialization - should not be converted
    public static StringBuffer sharedBuffer = new StringBuffer("Shared Data");

    // Method return value - not an assignment to a local variable
    public StringBuffer getNewBuffer(String initial) {
        return new StringBuffer(initial);
    }

    public void processBuffer(StringBuffer bufferParam) {
        // No new StringBuffer call, so no match
        System.out.println(bufferParam.toString());
    }
}
